import React, { useEffect, useState } from 'react';
import { ProfileInfo } from '@backstage/core-plugin-api';

import staticData from '../../helpers/data.json';

import { blue } from '@material-ui/core/colors';
import TreeView from '@material-ui/lab/TreeView';
import TreeItem from '@material-ui/lab/TreeItem';
import { Card, Divider, Typography, CardContent, } from '@material-ui/core';

import BookIcon from '@material-ui/icons/Book';
import AddCircleIcon from '@material-ui/icons/AddCircle';
import ExpandMoreIcon from '@material-ui/icons/ExpandMore';
import DocumentIcon from '@material-ui/icons/InsertDriveFile';
import ChevronRightIcon from '@material-ui/icons/ChevronRight';
import BookmarkBorderIcon from '@material-ui/icons/BookmarkBorder';
import ImportContactsIcon from '@material-ui/icons/ImportContacts';

import { CreateProjectDialog } from '../CreateProjectDialog/CreateProjectDialogComponent';

import { createProject, getProjects, getUserProjects } from '../../helpers/chatService';

export const ProjectsComponent = ({ onChangeProject, projectId, profile }: { onChangeProject: (codigo: number) => void, projectId: number, profile: ProfileInfo }) => {
  const [open, setOpen] = useState(false);
  const [_, setProjects] = useState<any[]>([]);
  const [userProjects, setUserProjects] = useState<any[]>([]);
  const [nombreProyecto, setProjectName] = useState('');
  const [descripcionProyecto, setProjectDescription] = useState('');

  const fetchUserProjects = async () => {
    const newProjects = await getUserProjects(profile.email!)
    setUserProjects(newProjects);
  };

  const fetchProjects = async () => {
    const allProjects = await getProjects();
    setProjects(allProjects);
  }

  const handleClickOpenDialog = () => {
    setOpen(true);
  };

  useEffect(() => {
    if (profile.email) {
      fetchUserProjects();
      fetchProjects();
    }
  }, [profile]);

  const handleClose = () => {
    setOpen(false);
  };

  const handleItemClick = (codigo: number) => {
    onChangeProject(codigo);
  };

  const onCreateProject = async (newProject: any) => {
    const resp = await createProject(newProject);
    setUserProjects([...userProjects, resp]);
    onChangeProject(resp.id);
  }

  const handleCrearProyecto = () => {
    const nuevoProyecto = {
      name: nombreProyecto,
      username: profile.email,
      description: descripcionProyecto,
    };
    onCreateProject(nuevoProyecto);

    setProjectName('');
    setProjectDescription('');
    handleClose();
  };

  interface RenderTree {
    id: string;
    name: string;
    type: string;
    children?: RenderTree[];
  }

  const [selectedNodeId, setSelectedNodeId] = useState<string>();

  const isActive = (node: RenderTree): Boolean => {
    if (node.id === selectedNodeId) {
      return true;
    }
    if (node.children) {
      return node.children.some((child: RenderTree) => isActive(child));
    }
    return false;
  };

  const renderTree = (nodes: RenderTree[]) => {

    const getIcon = (nodeType: string) => {
      switch (nodeType) {
        case 'project':
          return <BookmarkBorderIcon />;
        case 'epic':
          return <BookIcon />;
        case 'feature':
          return <ImportContactsIcon />;
        case 'story':
          return <DocumentIcon />;
        default:
          return null;
      }
    };

    const getColor = (node: RenderTree) => {
      if (isActive(node)) {
        switch (node.type) {
          case 'project':
            return '#58b757';
          case 'epic':
            return '#e39348';
          case 'feature':
            return '#4973ce';
          default:
            return '#9042fd';
        }
      } else {
        return 'grey';
      }
    };

    const handleNodeSelect = (node: RenderTree) => {
      if (node.type === 'story') {
        setSelectedNodeId(node.id);
      }
    };

    return nodes.map((node: RenderTree) => (
      <TreeItem
        key={node.id}
        nodeId={node.id}
        label={
          <div
            style={{ color: getColor(node) }}
            onClick={() => handleNodeSelect(node)}
          >
            <span style={{ marginRight: '8px' }}>{getIcon(node.type)}</span>
            {node.name}
          </div>
        }
      >
        {Array.isArray(node.children) ? renderTree(node.children) : null}
      </TreeItem>
    ))
  };

  return (
    <>
      <Card style={{ minHeight: '25rem', maxHeight: '50rem' }}>
        <CardContent>
          <Typography variant="h4" style={{ color: '#2e77d0' }}>
            <AddCircleIcon
              style={{
                color: blue[500],
                marginRight: '10px',
                cursor: 'pointer',
              }}
              onClick={handleClickOpenDialog}
            />
            Proyectos
          </Typography>
          <Divider />
          {userProjects.length === 0 ? (
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                alignItems: 'center',
                height: '100%',
              }}
            >
              <Typography variant="body2">
                Este es un asistente virtual que te ayudará a resolver tus dudas
                técnicas.
              </Typography>
            </div>
          ) : (
            <TreeView
              defaultCollapseIcon={<ExpandMoreIcon />}
              defaultExpandIcon={<ChevronRightIcon />}
            >
              {renderTree(staticData)}
            </TreeView>

          )}
        </CardContent>
      </Card>

      <CreateProjectDialog
        open={open}
        projectName={nombreProyecto}
        projectDescription={descripcionProyecto}
        handleClose={handleClose}
        handleCrearProyecto={handleCrearProyecto}
        setProjectName={setProjectName}
        setProjectDescription={setProjectDescription}
      />
    </>
  );
};
Tengo este componente en react, quiero que apliques la logica de estee compoente que es de un menu de proyectos con difrentes niveles de anidacion, aplica esa misma logica a este componente usando primeNg

Para convertir el componente de React que usa Material-UI a uno que usa PrimeNG, primero necesitas instalar PrimeNG y PrimeIcons si aún no lo has hecho. Puedes hacerlo ejecutando los siguientes comandos:

```bash
npm install primeng primeicons
```

Luego, puedes convertir el componente a uno que use PrimeNG. Aquí tienes un ejemplo de cómo hacerlo:

```tsx
import React, { useEffect, useState } from 'react';
import { ProfileInfo } from '@backstage/core-plugin-api';

import staticData from '../../helpers/data.json';

import { Tree } from 'primereact/tree';
import { Button } from 'primereact/button';
import { Dialog } from 'primereact/dialog';
import { InputText } from 'primereact/inputtext';
import { InputTextarea } from 'primereact/inputtextarea';
import { Card } from 'primereact/card';

import { createProject, getProjects, getUserProjects } from '../../helpers/chatService';

export const ProjectsComponent = ({ onChangeProject, projectId, profile }: { onChangeProject: (codigo: number) => void, projectId: number, profile: ProfileInfo }) => {
  const [open, setOpen] = useState(false);
  const [_, setProjects] = useState<any[]>([]);
  const [userProjects, setUserProjects] = useState<any[]>([]);
  const [nombreProyecto, setProjectName] = useState('');
  const [descripcionProyecto, setProjectDescription] = useState('');

  const fetchUserProjects = async () => {
    const newProjects = await getUserProjects(profile.email!)
    setUserProjects(newProjects);
  };

  const fetchProjects = async () => {
    const allProjects = await getProjects();
    setProjects(allProjects);
  }

  const handleClickOpenDialog = () => {
    setOpen(true);
  };

  useEffect(() => {
    if (profile.email) {
      fetchUserProjects();
      fetchProjects();
    }
  }, [profile]);

  const handleClose = () => {
    setOpen(false);
  };

  const handleItemClick = (codigo: number) => {
    onChangeProject(codigo);
  };

  const onCreateProject = async (newProject: any) => {
    const resp = await createProject(newProject);
    setUserProjects([...userProjects, resp]);
    onChangeProject(resp.id);
  }

  const handleCrearProyecto = () => {
    const nuevoProyecto = {
      name: nombreProyecto,
      username: profile.email,
      description: descripcionProyecto,
    };
    onCreateProject(nuevoProyecto);

    setProjectName('');
    setProjectDescription('');
    handleClose();
  };

  interface RenderTree {
    id: string;
    name: string;
    type: string;
    children?: RenderTree[];
  }

  const [selectedNodeId, setSelectedNodeId] = useState<string>();

  const isActive = (node: RenderTree): Boolean => {
    if (node.id === selectedNodeId) {
      return true;
    }
    if (node.children) {
      return node.children.some((child: RenderTree) => isActive(child));
    }
    return false;
  };

  const renderTree = (nodes: RenderTree[]) => {

    const getIcon = (nodeType: string) => {
      switch (nodeType) {
        case 'project':
          return 'pi pi-bookmark';
        case 'epic':
          return 'pi pi-book';
        case 'feature':
          return 'pi pi-book-open';
        case 'story':
          return 'pi pi-file';
        default:
          return null;
      }
    };

    const getColor = (node: RenderTree) => {
      if (isActive(node)) {
        switch (node.type) {
          case 'project':
            return '#58b757';
          case 'epic':
            return '#e39348';
          case 'feature':
            return '#4973ce';
          default:
            return '#9042fd';
        }
      } else {
        return 'grey';
      }
    };

    const handleNodeSelect = (node: RenderTree) => {
      if (node.type === 'story') {
        setSelectedNodeId(node.id);
      }
    };

    return nodes.map((node: RenderTree) => ({
      key: node.id,
      label: (
        <div
          style={{ color: getColor(node) }}
          onClick={() => handleNodeSelect(node)}
        >
          <i className={`pi ${getIcon(node.type)}`} style={{ marginRight: '8px' }}></i>
          {node.name}
        </div>
      ),
      children: Array.isArray(node.children) ? renderTree(node.children) : null
    }));
  };

  return (
    <>
      <Card style={{ minHeight: '25rem', maxHeight: '50rem' }}>
        <div className="p-card-content">
          <h4 style={{ color: '#2e77d0' }}>
            <Button
              icon="pi pi-plus"
              className="p-button-rounded p-button-text"
              style={{ color: '#2e77d0', marginRight: '10px' }}
              onClick={handleClickOpenDialog}
            />
            Proyectos
          </h4>
          <hr />
          {userProjects.length === 0 ? (
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                alignItems: 'center',
                height: '100%',
              }}
            >
              <p>
                Este es un asistente virtual que te ayudará a resolver tus dudas
                técnicas.
              </p>
            </div>
          ) : (
            <Tree value={renderTree(staticData)} />
          )}
        </div>
      </Card>

      <Dialog header="Crear Proyecto" visible={open} style={{ width: '50vw' }} onHide={handleClose}>
        <div className="p-fluid">
          <div className="p-field">
            <label htmlFor="projectName">Nombre del Proyecto</label>
            <InputText id="projectName" value={nombreProyecto} onChange={(e) => setProjectName(e.target.value)} />
          </div>
          <div className="p-field">
            <label htmlFor="projectDescription">Descripción del Proyecto</label>
            <InputTextarea id="projectDescription" value={descripcionProyecto} onChange={(e) => setProjectDescription(e.target.value)} rows={3} />
          </div>
          <div className="p-field">
            <Button label="Crear" icon="pi pi-check" onClick={handleCrearProyecto} />
          </div>
        </div>
      </Dialog>
    </>
  );
};
```

En este código, he reemplazado los componentes de Material-UI con componentes de PrimeNG. Aquí hay algunos puntos clave:

1. `TreeView` y `TreeItem` de Material-UI se han reemplazado con `Tree` de PrimeNG.
2. `Card`, `Button`, `Dialog`, `InputText`, y `InputTextarea` de PrimeNG se han utilizado en lugar de los componentes equivalentes de Material-UI.
3. Los íconos de Material-UI se han reemplazado con íconos de PrimeIcons.
4. La lógica de renderizado del árbol se ha adaptado para trabajar con la estructura de datos de PrimeNG.

